package app.truemotion.vector;
import android.content.*;import android.net.*;import java.io.*;
final class VectorMediaIO {
 static byte[] bytes(Context c,Uri uri,int limit)throws Exception{try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open document");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[32768];int n;while((n=in.read(block))!=-1){if(out.size()+(long)n>limit)throw new IOException(L10n.t("Слишком большой файл импорта"));WorkBudget.memory((out.size()+(long)n)*5);out.write(block,0,n);}return out.toByteArray();}}
 static File copy(Context c,Uri uri)throws Exception{File dir=new File(c.getFilesDir(),"media/vector-media");dir.mkdirs();String mime=c.getContentResolver().getType(uri),ext=mime==null?null:android.webkit.MimeTypeMap.getSingleton().getExtensionFromMimeType(mime);if(ext==null||!ext.matches("[a-zA-Z0-9]{1,8}"))ext="media";File out=new File(dir,java.util.UUID.randomUUID()+"."+ext);try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream dst=new FileOutputStream(out)){if(in==null)throw new IOException("Cannot open media");byte[] block=new byte[65536];int n;while((n=in.read(block))!=-1){if(out.getUsableSpace()<n+1024*1024)throw new IOException("Not enough storage");dst.write(block,0,n);}}catch(Exception e){out.delete();throw e;}return out;}
}
